"""Parse and key-identity pins for the three JavaScript IME settings pages.

The JS Services live in the ``McBopomofoWeb`` / ``McFoximWeb`` / ``McTabimWeb``
submodules; their PIME payload is ``<submodule>/output/pime/`` (``index.js``
there is the webpack bundle, untracked in both repos; the page files sit beside
it, tracked in the submodule). ``build.bat`` copies that directory into
``node/input_methods/<Name>/``, so the submodule copy is the source of truth.

The pins cover the two shapes that break silently: a page script that no longer
parses, and an ``onchange`` handler writing the wrong ``settings`` key, which
leaves the value the engine reads stale while the page looks saved.
"""

import os
import re
import subprocess
import unittest

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.path.pardir))

# the three JS Services, each a submodule with output/pime/ as its payload
PAGES = ("McBopomofoWeb", "McFoximWeb", "McTabimWeb")
TIMEOUT_SECONDS = 60

# ids whose settings key is the id itself; the radio and select ids carry an
# alias instead (esc_key writes esc_key_clear_entire_buffer, the letters radio
# writes letter_mode), which the preselect and default-block checks cover
DIRECT_KEYS = {
    "McBopomofoWeb": ("beep_on_error", "by_default_deactivated", "move_cursor",
                      "repeated_punctuation_choose_candidate",
                      "moving_cursor_option", "ctrl_enter_option"),
    "McFoximWeb": (),
    "McTabimWeb": (),
}


def pime_dir(name):
    return os.path.join(ROOT, name, "output", "pime")


def node_binary():
    for candidate in (os.path.join(ROOT, "node", "node.exe"),
                      os.path.join(ROOT, ".tools", "node", "node.exe")):
        if os.path.isfile(candidate):
            return candidate
    return None


def read(path):
    with open(path, encoding="utf-8") as handle:
        return handle.read()


def page_scripts(directory):
    js_dir = os.path.join(directory, "js")
    if not os.path.isdir(js_dir):
        return []
    return [os.path.join(js_dir, name) for name in sorted(os.listdir(js_dir))
            if name.endswith(".js") and not name.endswith(".min.js")]


def handler_blocks(script):
    """Map each ``$("id")`` to the body of its own onchange/onclick handler."""
    blocks = {}
    for match in re.finditer(r'\$\("([^"]+)"\)\.(?:onchange|onclick)\s*=', script):
        rest = script[match.end():]
        end = len(rest)
        depth = 0
        for index, char in enumerate(rest):
            if char == "{":
                depth += 1
            elif char == "}":
                depth -= 1
                if depth == 0:
                    end = index + 1
                    break
        blocks[match.group(1)] = rest[:end]
    return blocks


def control_ids(html):
    ids = set()
    for tag in re.findall(r"<(?:input|select)\b[^>]*>", html):
        found = re.search(r'id="([^"]+)"', tag)
        if found:
            ids.add(found.group(1))
    return ids


def wired_ids(script):
    """The ids the script touches, template-literal radio groups included.

    The three pages use three idioms: ``$("id")`` (McBopomofo),
    ``document.getElementById('id')`` held in a const or followed by
    ``.onchange`` / ``.addEventListener`` (McFoxim, McTabim), and the template
    literal ``table_${i}`` for a radio group generated in one loop.
    """
    ids = set(re.findall(r"""['"]([\w-]+)['"]""", script))
    prefixes = re.findall(r"`([A-Za-z_]+)\$\{", script)
    for eid in set(ids):
        for prefix in prefixes:
            if re.fullmatch(r"%s\d+" % re.escape(prefix), eid):
                ids.add(eid)
    return ids, prefixes


class JsOptionsPageTests(unittest.TestCase):

    def setUp(self):
        for name in PAGES:
            if not os.path.isdir(pime_dir(name)):
                self.skipTest("%s/output/pime missing (submodule not initialized)"
                              % name)

    def test_page_scripts_parse(self):
        node = node_binary()
        if node is None:
            self.skipTest("no bundled node runtime on this machine")
        for name in PAGES:
            scripts = page_scripts(pime_dir(name))
            self.assertTrue(scripts, "%s ships no page script" % name)
            for path in scripts:
                completed = subprocess.run([node, "--check", path], cwd=ROOT,
                                           capture_output=True, text=True,
                                           timeout=TIMEOUT_SECONDS)
                self.assertEqual(0, completed.returncode,
                                 "%s: %s" % (os.path.basename(path),
                                             completed.stderr.strip()))

    def test_every_control_has_a_handler(self):
        for name in PAGES:
            html = read(os.path.join(pime_dir(name), "options.html"))
            script = read(os.path.join(pime_dir(name), "js", "options.js"))
            ids, prefixes = wired_ids(script)
            missing = [eid for eid in control_ids(html)
                       if eid not in ids
                       and not any(re.fullmatch(r"%s\d+" % re.escape(p), eid)
                                   for p in prefixes)]
            self.assertEqual([], sorted(missing),
                             "%s: control the script never touches" % name)

    def test_direct_keys_keep_their_id_name(self):
        # The identity rule a stale-save bug breaks: a checkbox or number
        # control writes the settings key of its own id.
        for name in PAGES:
            script = read(os.path.join(pime_dir(name), "js", "options.js"))
            blocks = handler_blocks(script)
            for eid in DIRECT_KEYS[name]:
                self.assertIn(eid, blocks, "%s: no handler for %s" % (name, eid))
                self.assertIn("settings.%s =" % eid, blocks[eid],
                              "%s: %s writes %s instead of settings.%s"
                              % (name, eid,
                                 re.findall(r"settings\.(\w+)\s*=", blocks[eid]),
                                 eid))

    def test_mcbopomofo_saved_keys_are_declared(self):
        script = read(os.path.join(pime_dir("McBopomofoWeb"), "js", "options.js"))
        defaults = re.search(r"const defaultSettings = \{(.*?)\n  \};", script, re.S)
        self.assertIsNotNone(defaults, "no defaultSettings block")
        declared = set(re.findall(r"^\s*(\w+):", defaults.group(1), re.M))
        saved = set(re.findall(r"settings\.(\w+)\s*=", script))
        self.assertEqual(set(), saved - declared,
                         "saved key missing from defaultSettings: %s"
                         % sorted(saved - declared))

    def test_mcbopomofo_numeric_preselect_compares_loosely(self):
        # A handler that stores +$(id).value keeps the settings key a number
        # while option.value stays a string, so a strict === in that preselect
        # loop leaves the dropdown on its first item forever. String-valued
        # keys and the + coerced ones keep ===.
        script = read(os.path.join(pime_dir("McBopomofoWeb"), "js", "options.js"))
        numeric = set()
        for _eid, body in handler_blocks(script).items():
            for stored in re.findall(r'const value = \+\$\("[^"]+"\)\.value;'
                                     r'\s*settings\.(\w+) = value', body):
                numeric.add(stored)
        self.assertIn("moving_cursor_option", numeric,
                      "the number select still stores a number")
        for condition in re.findall(r"if \(([^)]+)\) \{\n\s*option\.selected", script):
            match = re.fullmatch(r"option\.value (===|==) settings\.(\w+)", condition)
            if match and match.group(2) in numeric:
                self.assertEqual("==", match.group(1),
                                 "strict compare on the number key %s" % match.group(2))


if __name__ == "__main__":
    unittest.main()
